<?xml version="1.0" encoding="UTF-8"?>
<ArdourMIDIBindings version="1.0.0" name="KeyLab Essential 49" manufacturer="Arturia">
<!--
    Arturia KeyLab Essential 49 in its normal (Analog Lab) mode, not in DAW mode.

    The keyboard has two MIDI ports and both must be connected to Ardour's
    "MIDI Control In":
      * "MIDI" port: faders and encoders as CCs on the keyboard's current
        MIDI channel (the channel of the keys, pitch bend and modulation
        wheel), so they are bound on all 16 channels below; pads as notes
        36-43 on channel 10.
      * "DAW" port: transport and utility buttons, as Mackie Control notes on
        channel 1, whatever the mode.

    Faders and encoders are absolute and not motorized: Ardour only follows a
    fader once its movement crosses the current value, so nothing jumps. The
    threshold additionally drops any step larger than itself, which loses the
    fader as soon as it is moved quickly (steps of 25 were measured), so it is
    set to its maximum: the crossing rule alone already prevents jumps.
    Encoder 9 (CC 17) and the pads are left free; the pads are meant to play
    a drum track.
-->
  <DeviceInfo bank-size="8" threshold="127"/>

<!-- Faders 1-8 and master fader, then encoders 1-8 (pan), repeated for each
     MIDI channel: Generic MIDI bindings are per channel, and these controls
     follow the keyboard's channel. -->
  <!-- channel 1 -->
  <Binding channel="1" ctl="73" uri="/route/gain B1"/>
  <Binding channel="1" ctl="75" uri="/route/gain B2"/>
  <Binding channel="1" ctl="79" uri="/route/gain B3"/>
  <Binding channel="1" ctl="72" uri="/route/gain B4"/>
  <Binding channel="1" ctl="80" uri="/route/gain B5"/>
  <Binding channel="1" ctl="81" uri="/route/gain B6"/>
  <Binding channel="1" ctl="82" uri="/route/gain B7"/>
  <Binding channel="1" ctl="83" uri="/route/gain B8"/>
  <Binding channel="1" ctl="85" uri="/bus/gain master"/>
  <Binding channel="1" ctl="74" uri="/route/pandirection B1"/>
  <Binding channel="1" ctl="71" uri="/route/pandirection B2"/>
  <Binding channel="1" ctl="76" uri="/route/pandirection B3"/>
  <Binding channel="1" ctl="77" uri="/route/pandirection B4"/>
  <Binding channel="1" ctl="93" uri="/route/pandirection B5"/>
  <Binding channel="1" ctl="18" uri="/route/pandirection B6"/>
  <Binding channel="1" ctl="19" uri="/route/pandirection B7"/>
